package devlab

import (
	"context"
	"errors"
	"os"

	"google.golang.org/protobuf/encoding/protojson"
	"google.golang.org/protobuf/proto"

	configv1 "lindm/gen/lindm/config/v1"
	"lindm/internal/config"
)

// ConfigureAssistance enables the embedded remote-assistance relay in the
// owned server and restarts it. Restarting preserves accounts, sessions and the
// isolated database; the relay credential secret is regenerated by lindmd.
// The configuration is the caller's exact nonsecret relay contract.
func (f *AuthorityFixture) ConfigureAssistance(ctx context.Context, assistance *configv1.AssistanceConfig) error {
	if f.closed || f.local == nil {
		return errors.New("assistance requires an open local authority fixture")
	}
	if assistance == nil {
		return errors.New("assistance configuration is required")
	}
	document, err := config.Load(f.configPath())
	if err != nil {
		return err
	}
	if document.Proto.GetAssistance() != nil {
		return errors.New("assistance is already configured")
	}
	document.Proto.Assistance = proto.CloneOf(assistance)
	encoded, err := protojson.Marshal(document.Proto)
	if err != nil {
		return err
	}
	if err := os.WriteFile(f.configPath(), encoded, 0600); err != nil {
		return err
	}
	return f.Restart(ctx)
}
